"""The budget's effort mapping: its data file, its rule, and the reasons it gives.

Experimental: :mod:`web_router.routing.params` is new and may change before 1.0.
Kept apart from :mod:`web_router.constants`, so that file stops growing.
"""

from __future__ import annotations

from typing import Final

EFFORTS_DATA_DIR = "data"
EFFORTS_DATA_FILE = "efforts.json"
"""The research effort table, generated by ``make efforts`` from the frozen results; never edited by hand."""

MIN_MEASURED_EFFORTS = 2
"""The fewest measured efforts a backend's effort is mapped on: with one, there is nothing to compare it to."""

FLOOR_TOLERANCE = 1e-12
"""Keeps a gap equal to the floor, computed from different counts, inside it, as route-eval's ranking does."""

EFFORT_RULE = (
    "Under a budget with a cost or time cap, research runs at the cheapest effort whose accuracy is within the "
    "noise floor of the most accurate measured effort that fits what is left: an accuracy gap smaller than a "
    "rerun's spread does not tell two efforts apart, so cost decides, then p90 latency, then the lower effort. "
    "An effort fits when its list price is known and within the cost cap and its p90 is within the time cap; an "
    "unknown p90 fits unless the budget is strict. A backend with fewer than two measured efforts keeps its "
    "default, and so does a call whose caller set the effort."
)
"""The rule :func:`web_router.routing.params.map_effort` applies, in words; ``efforts.json`` carries it too."""

PARAMS_SOURCE_BUDGET: Final = "budget"
"""``params_source`` when the budget's mapping chose the params."""
PARAMS_SOURCE_CALLER: Final = "caller"
"""``params_source`` when the caller set them; the budget never changes them."""
PARAMS_SOURCE_ROUTER: Final = "router"
"""``params_source`` when a router set them and they passed the merge rule's checks."""

DEFAULT_EFFORT_NAME = "default"
"""How a reason names the effort a call gets when it sets none."""

MSG_EFFORT_NO_BUDGET = "no cost or time cap: research:{provider} runs at its default effort"
MSG_EFFORT_CALLER = "effort {effort} was set by the caller, and the budget never changes it"
MSG_EFFORT_UNMEASURED = (
    "research:{provider} has fewer than {min} measured efforts in {set}: it runs at its default effort"
)
MSG_EFFORT_NONE_FITS_EVERY = (
    "no research effort the budget maps ({efforts}) fits it on every backend in the order ({providers}): "
    "none is set, and each runs at its own default"
)
"""``params_reason`` when the request, shared by every backend in the order, can carry no mapped effort."""
MSG_EFFORT_NONE_FITS = "no measured effort of research:{provider} fits the budget: it runs at its default effort"
MSG_EFFORT_CHOSEN = (
    "effort {effort} ({accuracy:.1%}): the cheapest measured effort of research:{provider} within the "
    "{floor:.1f}-point noise floor of the most accurate one that fits the budget, {best} ({best_accuracy:.1%})"
)

MSG_MISFIT_UNKNOWN_PRICE = "research:{provider} at effort {effort} has no known price, so it never fits a cost cap"
MSG_MISFIT_COST = "research:{provider} at effort {effort} is estimated at ${cost:g}, over the ${cap:g} cost cap"
MSG_MISFIT_TIME = "research:{provider} at effort {effort} has a p90 of {p90:g}s, over the {cap:g}s time limit"
MSG_MISFIT_STRICT = "research:{provider} at effort {effort} has no measured p90, and the budget is strict"
